class PositiveNumber:
    """Descriptor that ensures a value is positive."""
    def __init__(self, name=None):
        self.name = name or "_value"

    def __get__(self, obj, objtype=None):
        if obj is None:
            return self
        return getattr(obj, self.name, 0)

    def __set__(self, obj, value):
        if value < 0:
            raise ValueError(f"{self.name} must be positive, got {value}")
        setattr(obj, self.name, value)

    def __delete__(self, obj):
        delattr(obj, self.name)

class Order:
    # Descriptors as class variables:
    quantity = PositiveNumber("_quantity")
    price = PositiveNumber("_price")

    def __init__(self, item: str, quantity: int, price: float):
        self.item = item
        self.quantity = quantity  # Goes through __set__
        self.price = price

    @property
    def total(self):
        return self.quantity * self.price

order = Order("Widget", 10, 5.99)
print(order.total)  # 59.9

