# Inheritance — IS-A relationship:
class Animal:
    def breathe(self):
        return "Breathing"

class Dog(Animal):  # Dog IS-A Animal
    def bark(self):
        return "Woof!"

# Composition — HAS-A relationship:
class Engine:
    def start(self):
        return "Engine started"

    def stop(self):
        return "Engine stopped"

class Wheels:
    def rotate(self):
        return "Wheels rotating"

class Car:  # Car HAS-A Engine, HAS-A Wheels
    def __init__(self):
        self.engine = Engine()
        self.wheels = [Wheels() for _ in range(4)]

    def drive(self):
        return f"{self.engine.start()} and {self.wheels[0].rotate()}"

# When to use inheritance:
# · Clear hierarchical relationship (Dog IS-A Animal)
# · Subclass is a specialization of parent
# · You'll use the subclass polymorphically

# When to use composition:
# · HAS-A relationship (Car HAS-A Engine)
# · You want to reuse behavior but not interface
# · You need flexibility (change components at runtime)

# Example: mix of both:
class Logger:
    def log(self, msg):
        print(f"LOG: {msg}")

class User:
    def __init__(self, name):
        self.name = name
        self.logger = Logger()  # Composition

    def save(self):
        self.logger.log(f"Saving user {self.name}")
        # Save logic...

# Prefer composition over inheritance:
# · More flexible
# · Easier to test
# · Avoids deep inheritance hierarchies
# · Runtime swappable behavior (Strategy pattern)

