# Mixins are classes that provide reusable functionality
# They are meant to be combined with other classes

class JSONMixin:
    """Add JSON serialization to any class."""
    def to_json(self) -> str:
        import json
        return json.dumps(self.__dict__)

    @classmethod
    def from_json(cls, json_str: str):
        import json
        data = json.loads(json_str)
        return cls(**data)

class LogMixin:
    """Add logging capability."""
    def log(self, message: str):
        print(f"[{self.__class__.__name__}] {message}")

class TimestampMixin:
    """Add timestamp on creation."""
    def __init_subclass__(cls, **kwargs):
        super().__init_subclass__(**kwargs)
        cls.created_at = None

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        import time
        self.created_at = time.time()

# Now compose them:
class User(JSONMixin, LogMixin, TimestampMixin):
    def __init__(self, name: str, email: str):
        super().__init__()  # Important for mixins!
        self.name = name
        self.email = email

user = User("Alice", "alice@example.com")
print(user.to_json())  # {"name": "Alice", "email": "alice@example.com", "created_at": ...}
print(user.log("User created"))  # [User] User created
print(user.created_at)  # 1234567890.123

