# Custom metaclass:
class SingletonMeta(type):
    """Metaclass that creates singleton classes."""
    _instances = {}

    def __call__(cls, *args, **kwargs):
        if cls not in cls._instances:
            cls._instances[cls] = super().__call__(*args, **kwargs)
        return cls._instances[cls]

class Config(metaclass=SingletonMeta):
    def __init__(self):
        self.settings = {}

c1 = Config()
c2 = Config()
print(c1 is c2)   # True (same instance!)

# Metaclass to auto-register subclasses:
class RegistryMeta(type):
    _registry = {}

    def __new__(mcs, name, bases, namespace):
        cls = super().__new__(mcs, name, bases, namespace)
        if name not in ("BasePlugin",):
            mcs._registry[name] = cls
        return cls

    @classmethod
    def get_plugins(mcs):
        return dict(mcs._registry)

class BasePlugin(metaclass=RegistryMeta):
    """All plugins register automatically."""
    pass

class PDFPlugin(BasePlugin):
    pass

class ImagePlugin(BasePlugin):
    pass

print(RegistryMeta.get_plugins())
# {'PDFPlugin': <class '__main__.PDFPlugin'>, 'ImagePlugin': <class '__main__.ImagePlugin'>}

# Metaclass to add methods automatically:
class AutoStrMeta(type):
    def __new__(mcs, name, bases, namespace):
        if "__str__" not in namespace and "__init__" in namespace:
            def __str__(self):
                attrs = ", ".join(f"{k}={v}" for k, v in self.__dict__.items())
                return f"{name}({attrs})"
            namespace["__str__"] = __str__
        return super().__new__(mcs, name, bases, namespace)

class Item(metaclass=AutoStrMeta):
    def __init__(self, name, price):
        self.name = name
        self.price = price

print(Item("Widget", 9.99))  # Item(name=Widget, price=9.99)
